#include <iostream>

int main() {
    // Khai báo biến với kiểu dấu phẩy động double
    double radius;
    double area;

    // Gán giá trị bán kính cố định
    radius = 20.0;

    // Tính diện tích với xấp xỉ số pi 3.14159
    area = radius * radius * 3.14159;

    // Xuất kết quả
    std::cout << "The area is " << area << std::endl;

    return 0;
}

#include <iostream>

